python
def priorityBasketThresholdFile(readings, k):
    a=readings
    out=[]
    import heapq
    heap=a[:]
    heapq.heapify(heap)
    while heap: out.append(heapq.heappop(heap))
    return sum(x>=k for x in out)


java
class Solution {
  public int priorityBasketThresholdFile(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {PriorityQueue<Integer>heap=new PriorityQueue<>();for(int x:a)heap.add(x);while(!heap.isEmpty())out.add(heap.remove());}
    int answer=0;for(int x:out)if(x>=k)answer++;return answer;
  }
}
